def _is_trusted_internal_caller(request: Request | None) -> bool:
    user = getattr(getattr(request, "state", None), "user", None)
    return getattr(user, "system_role", None) == INTERNAL_SYSTEM_ROLE


def _strip_workbench_channels(value: Any) -> Any:
    if not isinstance(value, Mapping):
        return value
    sanitized = dict(value)
    for key in (*_WORKBENCH_CONTEXT_KEYS, *_WORKBENCH_SECRET_KEYS):
        sanitized.pop(key, None)
    return sanitized


def _sanitize_run_config(request_config: dict[str, Any] | None) -> dict[str, Any] | None:
    """Remove reserved Workbench channels before config persistence or execution."""
    if request_config is None:
        return None
    sanitized = dict(request_config)
    for container_name in ("configurable", "context"):
        if container_name in sanitized:
            sanitized[container_name] = _strip_workbench_channels(sanitized[container_name])
    for key in (*_WORKBENCH_CONTEXT_KEYS, *_WORKBENCH_SECRET_KEYS):
        sanitized.pop(key, None)
    return sanitized


def _normalize_workbench_scope(value: Any) -> dict[str, Any] | None:
    if not isinstance(value, Mapping):
        return None
    if not set(value).issubset(_WORKBENCH_SCOPE_KEYS):
        return None
    run_id = value.get("runId")
    runtime_attempt_id = value.get("runtimeAttemptId")
    requested_artifact_kinds = value.get("requestedArtifactKinds")
    knowledge_enabled = value.get("knowledgeEnabled")
    if (
        not isinstance(run_id, str)
        or not run_id
        or not isinstance(runtime_attempt_id, str)
        or not runtime_attempt_id
        or (knowledge_enabled is not None and knowledge_enabled is not True)
        or (
            requested_artifact_kinds is not None
            and (
                not isinstance(requested_artifact_kinds, list)
                or len(requested_artifact_kinds) > len(_WORKBENCH_REQUESTED_ARTIFACT_KINDS)
                or any(
                    not isinstance(kind, str)
                    or kind not in _WORKBENCH_REQUESTED_ARTIFACT_KINDS
                    for kind in requested_artifact_kinds
                )
                or len(set(requested_artifact_kinds)) != len(requested_artifact_kinds)
            )
        )
    ):
        return None
    return {key: value[key] for key in _WORKBENCH_SCOPE_KEYS if key in value}


def _normalize_workbench_secrets(value: Any) -> dict[str, str]:
    if not isinstance(value, Mapping):
        return {}
    return {
        key: secret
        for key, secret in value.items()
        if key in _WORKBENCH_SECRET_KEYS and isinstance(secret, str) and secret
    }

